    private static class ManualSaleRow {
        android.widget.AutoCompleteTextView product;
        EditText quantity;
        String discountKind="percent";
        double discountValue=0;
    }
    private String manualSaleRequestId="",manualSaleSignature="";
    private void manualDiscountDialog(String kind,double value,java.util.function.BiConsumer<String,Double> done){
        LinearLayout box=baseRoot();box.setPadding(dp(16),dp(10),dp(16),dp(10));
        Spinner units=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"אחוז הנחה","סכום להפחתה בשקלים"});units.setAdapter(adapter);units.setSelection("amount".equals(kind)?1:0);box.addView(units);
        EditText amount=input("ערך ההנחה");amount.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);amount.setText(String.valueOf(value));box.addView(amount);box.addView(text("הסכום מופחת מהמחיר הרגיל. בהנחה לכל מוצר — מכל יחידה.",16,false));
        AlertDialog dlg=new AlertDialog.Builder(this).setTitle("הגדרת הנחה").setView(box).setNegativeButton("ביטול",null).setPositiveButton("אישור",null).create();dlg.setOnShowListener(v->dlg.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(w->{try{double n=Double.parseDouble(amount.getText().toString().trim());if(Double.isNaN(n)||Double.isInfinite(n)||n<0||(units.getSelectedItemPosition()==0&&n>100))throw new Exception();done.accept(units.getSelectedItemPosition()==0?"percent":"amount",n);dlg.dismiss();}catch(Exception e){amount.setError("יש להזין הנחה תקינה");}}));dlg.show();
    }
    private void showSpecialSaleNative(){
        buildShell("מכירה מיוחדת",this::showAdminHome,false);
        content.addView(text("רישום מכירה שכבר שולמה. השמירה מפחיתה מהמלאי ואינה מחייבת כרטיס אשראי.",16,false));
        Spinner mode=new Spinner(this);mode.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"מחיר רגיל","מחיר עלות","הנחה לכל מוצר","הנחה לכל המכירה"}));content.addView(mode,new LinearLayout.LayoutParams(-1,dp(56)));
        final String[] kind={"percent"};final double[] value={0};
        Button saleDiscount=button("הגדרת הנחה לכל המכירה",Color.WHITE,blue);content.addView(saleDiscount);saleDiscount.setVisibility(View.GONE);
        LinearLayout rowsBox=baseRoot();content.addView(rowsBox);java.util.List<ManualSaleRow> rows=new ArrayList<>();final Runnable[] draw={null};
        draw[0]=()->{rowsBox.removeAllViews();for(ManualSaleRow row:rows){if(row.product.getParent()!=null)((android.view.ViewGroup)row.product.getParent()).removeView(row.product);if(row.quantity.getParent()!=null)((android.view.ViewGroup)row.quantity.getParent()).removeView(row.quantity);LinearLayout c=card();c.addView(label("מוצר"));c.addView(row.product,new LinearLayout.LayoutParams(-1,dp(56)));c.addView(label("כמות"));c.addView(row.quantity);if(mode.getSelectedItemPosition()==2){Button discount=button("הנחה: "+row.discountValue+("percent".equals(row.discountKind)?"%":" ₪")+" — עריכה",Color.WHITE,blue);discount.setOnClickListener(v->manualDiscountDialog(row.discountKind,row.discountValue,(k,n)->{row.discountKind=k;row.discountValue=n;draw[0].run();}));c.addView(discount);}Button remove=button("הסר מוצר",Color.WHITE,red);remove.setOnClickListener(v->{rows.remove(row);draw[0].run();});c.addView(remove);rowsBox.addView(c);}};
        Runnable add=()->{ManualSaleRow r=new ManualSaleRow();r.product=productNameInputNative();configureAppInput(r.product);r.quantity=input("כמות");r.quantity.setInputType(InputType.TYPE_CLASS_NUMBER);r.quantity.setText("1");rows.add(r);draw[0].run();};add.run();
        Button addButton=button("+ הוסף מוצר",Color.WHITE,blue);addButton.setOnClickListener(v->add.run());content.addView(addButton);
        saleDiscount.setOnClickListener(v->manualDiscountDialog(kind[0],value[0],(k,n)->{kind[0]=k;value[0]=n;saleDiscount.setText("הנחה לכל המכירה: "+n+("percent".equals(k)?"%":" ₪"));}));
        mode.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){saleDiscount.setVisibility(pos==3?View.VISIBLE:View.GONE);draw[0].run();if(pos==3)saleDiscount.performClick();else if(pos==2&&!rows.isEmpty()){ManualSaleRow row=rows.get(0);manualDiscountDialog(row.discountKind,row.discountValue,(k,n)->{row.discountKind=k;row.discountValue=n;draw[0].run();});}}});
        EditText note=input("הערה");content.addView(label("הערה"));content.addView(note);
        Button save=button("בדיקת סכום ושמירת מכירה",green,Color.WHITE);content.addView(save,new LinearLayout.LayoutParams(-1,dp(60)));
        save.setOnClickListener(v->{try{JSONArray items=new JSONArray();java.util.Set<String> seen=new java.util.HashSet<>();for(ManualSaleRow row:rows){Product p=findProductByNameNative(row.product.getText().toString());if(p==null)throw new Exception("יש לבחור מוצר קיים");if(!seen.add(p.id))throw new Exception("יש לאחד שורות של אותו מוצר");int q=Integer.parseInt(row.quantity.getText().toString().trim());if(q<=0)throw new Exception("כמות לא תקינה");JSONObject item=new JSONObject();item.put("product_id",p.id);item.put("quantity",q);item.put("discount_kind",row.discountKind);item.put("discount_value",row.discountValue);items.put(item);}if(items.length()==0)throw new Exception("יש לבחור מוצר");JSONObject body=new JSONObject();body.put("p_items",items);body.put("p_mode",new String[]{"regular","cost","item_discount","sale_discount"}[mode.getSelectedItemPosition()]);body.put("p_discount_kind",kind[0]);body.put("p_discount_value",value[0]);body.put("p_note",note.getText().toString().trim());String signature=body.toString();if(!signature.equals(manualSaleSignature)){manualSaleSignature=signature;manualSaleRequestId=java.util.UUID.randomUUID().toString();}body.put("p_request_id",manualSaleRequestId);body.put("p_commit",false);save.setEnabled(false);io.execute(()->{try{JSONObject quote=new JSONObject(requestRaw("POST","/rest/v1/rpc/price_manual_sale",body,true));if(quote.optBoolean("saved",false)){main.post(()->{manualSaleRequestId="";manualSaleSignature="";Toast.makeText(this,"המכירה כבר נשמרה בהצלחה",Toast.LENGTH_LONG).show();showSpecialSaleNative();});loadData(()->{});return;}StringBuilder message=new StringBuilder();JSONArray lines=quote.getJSONArray("lines");for(int i=0;i<lines.length();i++){JSONObject line=lines.getJSONObject(i);message.append(line.optString("name")).append(" × ").append(line.optInt("quantity")).append(" = ").append(String.format(Locale.ROOT,"%.2f ₪",line.optDouble("line_amount"))).append("\n");}message.append("\nסה״כ: ").append(String.format(Locale.ROOT,"%.2f ₪",quote.getDouble("total"))).append("\nלשמור ולהפחית מהמלאי?");main.post(()->new AlertDialog.Builder(this).setTitle("אישור מכירה מיוחדת").setMessage(message.toString()).setNegativeButton("ביטול",(d,w)->save.setEnabled(true)).setOnCancelListener(d->save.setEnabled(true)).setPositiveButton("שמור",(d,w)->commitManualSale(body,quote,save)).show());}catch(Exception e){main.post(()->{save.setEnabled(true);Toast.makeText(this,"בדיקת המכירה נכשלה: "+safeMsg(e),Toast.LENGTH_LONG).show();});}});}catch(Exception e){Toast.makeText(this,safeMsg(e),Toast.LENGTH_LONG).show();}});
    }
    private void commitManualSale(JSONObject body,JSONObject quote,Button save){
        io.execute(()->{try{body.put("p_commit",true);body.put("p_expected_total",quote.getDouble("total"));requestRaw("POST","/rest/v1/rpc/price_manual_sale",body,true);manualSaleRequestId="";manualSaleSignature="";main.post(()->{Toast.makeText(this,"המכירה נשמרה והמלאי עודכן",Toast.LENGTH_LONG).show();showSpecialSaleNative();});loadData(()->{});}catch(Exception e){main.post(()->{save.setEnabled(true);Toast.makeText(this,"שמירת המכירה נכשלה: "+safeMsg(e),Toast.LENGTH_LONG).show();});}});
    }
    private LinearLayout compactAdminRow(String[] values,float[] weights,boolean header,int index){
        LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);row.setBackgroundColor(header?Color.rgb(234,240,245):(index%2==0?Color.WHITE:Color.rgb(245,248,249)));row.setMinimumHeight(dp(42));
        for(int j=0;j<values.length;j++){TextView cell=text(values[j],header?15:16,header||j==1);cell.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);cell.setPadding(dp(10),dp(9),dp(10),dp(9));row.addView(cell,new LinearLayout.LayoutParams(0,-2,weights[j]));}return row;
    }
